const source = $json ?? {};
function textFrom(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(textFrom).filter(Boolean).join('\n\n').trim();
  if (!value || typeof value !== 'object') return '';
  for (const key of ['output', 'text', 'content', 'response', 'answer', 'message']) {
    const candidate = textFrom(value[key]);
    if (candidate) return candidate;
  }
  for (const key of ['messages', 'generations', 'data']) {
    const candidate = textFrom(value[key]);
    if (candidate) return candidate;
  }
  return '';
}
const delivery = textFrom(source).trim();
if (!delivery) {
  throw new Error(`EMPTY_DRAGON_DELIVERY: available keys: ${Object.keys(source).join(', ') || '(none)'}`);
}
const request = String($('Authorize & Classify').item.json.body || '');
const oneSentence = /\b(?:one|a single|1) (?:short )?sentence\b|(?:جملة (?:قصيرة )?واحدة|جملة واحدة قصيرة)/iu.test(request);
const threeBullets = /\b(?:three|3) (?:short )?(?:bullets|bullet points)\b|(?:ثلاث|٣|3) نقاط/u.test(request.toLowerCase());
if (oneSentence) {
  const sentences = delivery.split(/[.!?؟。]+(?:\s|$)/u).filter(part => part.trim());
  if (sentences.length !== 1 || /[\r\n]/u.test(delivery) || delivery.split(/\s+/u).length > 35)
    throw new Error('DRAQON_EXPECTED_ONE_SHORT_SENTENCE');
}
if (threeBullets) {
  const lines = delivery.split(/\r?\n/u).map(line => line.trim()).filter(Boolean);
  const bullet = /^(?:[-*•]|[1-3١-٣][.)])\s+\S/u;
  if (lines.length !== 3 || lines.some(line => !bullet.test(line) || line.split(/\s+/u).length > 45))
    throw new Error('DRAQON_EXPECTED_THREE_SHORT_BULLETS');
}
if (delivery.length > 12000) throw new Error('DRAQON_DRAFT_TOO_LARGE');
return [{ json: { delivery, deliveryLength: delivery.length, normalizedAt: new Date().toISOString() } }];

const rows = $json.body;
if (!Array.isArray(rows) || rows.length !== 1 || !rows[0].execution_id || !['processing','completed','failed'].includes(rows[0].status)) {
  throw new Error('DRAQON_LOCK_LOOKUP_INDETERMINATE');
}
const owned = String(rows[0].execution_id) === String($execution.id) && rows[0].status === 'processing';
return [{ json: { owned } }];

const rows = $json.body;
if (!Array.isArray(rows) || rows.length !== 1 || rows[0].status !== 'completed' || String(rows[0].execution_id) !== String($execution.id) || !rows[0].finished_at) {
  throw new Error('DRAQON_TERMINAL_WRITE_UNCONFIRMED');
}
return [{ json: { status: 'completed', executionId: String($execution.id) } }];

const rows = $json.body;
if (!Array.isArray(rows) || rows.length !== 1 || rows[0].status !== 'failed' || String(rows[0].execution_id) !== String($execution.id) || !rows[0].finished_at) {
  throw new Error('DRAQON_TERMINAL_WRITE_UNCONFIRMED');
}
return [{ json: { status: 'failed', executionId: String($execution.id) } }];
